import csv
import os

import numpy as np
from sklearn.mixture import GaussianMixture


# Generated by ChatGPT


def find_gmm_clusters(image, N=32, threshold_percentile=99,
                      intensity_power=1.0, random_state=42):

    image = np.asarray(image, dtype=float)

    if image.ndim != 2:
        raise ValueError("Image must be 2D.")

    valid = np.isfinite(image)
    if not valid.any():
        raise ValueError("Image contains no finite pixels.")

    height, width = image.shape
    threshold = np.percentile(image[valid], threshold_percentile)

    y, x = np.where(valid & (image > threshold))
    X = np.column_stack((x, y))
    intensities = image[y, x]

    if len(X) < N:
        raise ValueError("Not enough pixels for N clusters.")

    gmm = GaussianMixture(
        n_components=N,
        covariance_type="full",
        n_init=5,
        max_iter=300,
        reg_covar=1e-3,
        random_state=random_state
    ).fit(X)

    probabilities = gmm.predict_proba(X)

    spots = extract_spots(
        X, intensities, threshold, gmm, probabilities,
        intensity_power, width, height
    )

    return {
        "spots": spots,
        "features": extract_features(spots, width, height),
        "centers": gmm.means_,
        "covariances": gmm.covariances_,
        "labels": probabilities.argmax(axis=1),
        "probabilities": probabilities,
        "coordinates": X,
        "threshold": threshold,
        "gmm": gmm
    }


def extract_spots(X, intensities, threshold, gmm, probabilities,
                  intensity_power=1.0, width=None, height=None):

    excess = np.maximum(intensities - threshold, 0)
    spots = []

    for k in range(gmm.n_components):

        weights = probabilities[:, k] * excess**intensity_power
        if weights.sum() <= 1e-12:
            weights = probabilities[:, k]

        center = np.average(X, axis=0, weights=weights)
        cov = gmm.covariances_[k]

        eigvals, eigvecs = np.linalg.eigh(cov)
        order = np.argsort(eigvals)[::-1]
        eigvals, eigvecs = eigvals[order], eigvecs[:, order]

        major, minor = np.sqrt(eigvals)
        angle = np.degrees(np.arctan2(eigvecs[1, 0], eigvecs[0, 0]))

        eccentricity = np.sqrt(
            max(0, 1 - eigvals[1] / (eigvals[0] + 1e-10))
        )

        spots.append({
            "center_x": center[0],
            "center_y": center[1],
            "gmm_center_x": gmm.means_[k, 0],
            "gmm_center_y": gmm.means_[k, 1],
            "covariance": cov,
            "sigma_major": major,
            "sigma_minor": minor,
            "fwhm_major": 2.35482 * major,
            "fwhm_minor": 2.35482 * minor,
            "orientation_deg": angle,
            "integrated_intensity": np.sum(probabilities[:, k] * excess),
            "mixture_weight": gmm.weights_[k],
            "eccentricity": eccentricity
        })

    cx, cy = width / 2, height / 2

    return sorted(
        spots,
        key=lambda s: np.arctan2(s["center_y"] - cy, s["center_x"] - cx)
    )


def extract_features(spots, width, height):

    cx, cy = width / 2, height / 2
    features = []

    for s in spots:
        angle = np.radians(s["orientation_deg"])

        features.extend([
            (s["center_x"] - cx) / cx,
            (s["center_y"] - cy) / cy,
            s["sigma_major"] / width,
            s["sigma_minor"] / height,
            np.log1p(max(s["integrated_intensity"], 0)),
            np.sin(2 * angle),
            np.cos(2 * angle),
            #s["eccentricity"]
        ])

    return np.asarray(features, dtype=np.float32)

def save_gmm_results(
    accumulated_file_path,
    file_name,
    hex_x,
    hex_z,
    features
):
    file_exists = (
        os.path.exists(accumulated_file_path)
        and os.path.getsize(accumulated_file_path) > 0
    )

    with open(accumulated_file_path, "a", newline="") as f:
        writer = csv.writer(f)

        # Feature names become column headers
        if not file_exists:
            header = ["filename", "hex_x", "hex_z", "center_x", "center_y", "sigma_major", "sigma_minor", "integrated_intensity", "orientation_sin", "orientation_cos"]
            writer.writerow(header)


        # Feature values are written into a single row
        row = [file_name, hex_x, hex_z] + list(features)
        writer.writerow(row)